import {Tab, Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import * as React from 'react'
import {Suspense} from 'react'

import useDocumentTitle from '../../../hooks/useDocumentTitle'
import {ROOT_PROJECT_ID} from '../../../types'
import tabStyles from '../../common/OverviewTab/OverviewTab.module.css'
import PageTitle from '../../common/PageTitle/PageTitle'
import BuildProblems from '../../packages/Problems/BuildProblems/BuildProblems'
import {
  BUILD_PROBLEMS_TAB_LABEL,
  Problems,
  TESTS_TAB_LABEL,
} from '../../packages/Problems/Problems.types'
import {useProjectIdFilter} from '../../packages/Problems/ProjectBuildTypeFilter/ProjectBuildTypeFilter.hooks'
import TestProblems from '../../packages/Problems/TestProblems/TestProblems'

import {useInvestigationTab} from './InvestigationsPage.hooks'

function InvestigationsPage() {
  useDocumentTitle(`My investigations - TeamCity`)

  const {investigationsTab, onSelect} = useInvestigationTab()

  const filter = useProjectIdFilter()
  const projectId = filter.projectId ?? ROOT_PROJECT_ID

  return (
    <>
      <PageTitle>{'My investigations'}</PageTitle>

      <Tabs selected={investigationsTab} onSelect={onSelect} className={tabStyles.tabs}>
        <Tab id={Problems.TESTS} title={TESTS_TAB_LABEL}>
          <Suspense>
            <TestProblems projectId={projectId} onlyInvestigated />
          </Suspense>
        </Tab>
        <Tab id={Problems.BUILD_PROBLEMS} title={BUILD_PROBLEMS_TAB_LABEL}>
          <Suspense>
            <BuildProblems projectId={projectId} onlyInvestigated />
          </Suspense>
        </Tab>
      </Tabs>
    </>
  )
}

export default React.memo(InvestigationsPage)
